if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{management_mutate($_POST);set_flash(__t('Changes saved.','تغییرات ذخیره شد.','بدلونونه خوندي شول.'),'success');redirect(BASE_URL.'modules/management.php');}catch(Throwable $e){http_response_code($e->getCode()===403?403:422);$error=$e instanceof PDOException?__t('Could not save. Check duplicate usernames.','ذخیره نشد؛ نام استفاده‌کننده را بررسی کنید.','خوندي نه شو؛ کارن نوم وګورئ.'):public_error($e);}
