function manage_input($name,$label,$type='text',$value=''){echo '<label>'.sanitize($label).'<input class="form-control" name="'.sanitize($name).'" type="'.sanitize($type).'" value="'.sanitize($value).'" required '.($type==='password'?'autocomplete="new-password" minlength="12"':'').'></label>';}
function manage_policies($type,$id){
    echo '<input name="policy_matrix_started" type="hidden" value="1">';$groups=[];foreach(domain_catalog() as $key=>$label)$groups[explode('.',$key)[0]][$key]=$label;
    foreach($groups as $module=>$features){echo '<details class="policy-group"><summary>'.sanitize(domain_label($module)).'</summary>';
    foreach($features as $key=>$label){$p=$id?domain_policy($type,$id,$key):null;$enabled=$p['enabled']??($type==='owner_user'?0:1);
        echo '<div class="policy-row"><label>'.sanitize(domain_label($key)).'<select name="policies['.$key.'][enabled]" class="form-control"><option value="1"'.($enabled?' selected':'').'>'.__t('Enabled','فعال','فعال').'</option><option value="0"'.(!$enabled?' selected':'').'>'.__t('Disabled','غیرفعال','بند').'</option></select></label><label>'.__t('When disabled','هنگام غیرفعال‌بودن','کله چې بند وي').'<select class="form-control" name="policies['.$key.'][visibility]"><option value="hidden">'.__t('Hidden','پنهان','پټ').'</option><option value="locked"'.(($p['visibility']??'')==='locked'?' selected':'').'>'.__t('Show locked','نمایش قفل','قفل وښایئ').'</option></select></label>';
        foreach(['daily_limit'=>__t('Daily limit','حد روزانه','ورځنی حد'),'monthly_limit'=>__t('Monthly limit','حد ماهانه','میاشتنی حد')] as $k=>$l)echo '<label>'.sanitize($l).'<input class="form-control" type="number" min="0" max="1000000" placeholder="∞" name="policies['.$key.']['.$k.']" value="'.sanitize($p[$k]??'').'"></label>';
        echo '</div>';
    }echo '</details>';}
    echo '<input name="policy_matrix_complete" type="hidden" value="'.count(domain_catalog()).'">';
}
?>
<h2><?= sanitize($pageTitle) ?></h2>
<p><?= __t('Central access and owner approval are both required for employee AI. A hidden or locked service is also blocked on the server. Empty quotas are unlimited; zero blocks use.','برای AI کارمند، اجازهٔ مدیریت مرکزی و مالک هر دو لازم است. خدمت پنهان یا قفل‌شده در سرور هم بسته است. سهمیهٔ خالی بدون محدودیت؛ صفر یعنی بسته.','د کارمند AI لپاره د مرکزي مدیر او مالک دواړو اجازه اړینه ده.') ?></p>
