<details><summary><?= __t('Create employee','ساخت حساب کارمند','کارمند جوړول') ?></summary><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="create_staff"><input type="hidden" name="business_id" value="<?= (int)$b['id'] ?>"><div class="form-grid"><?php manage_input('fullname',__t('Full name','نام مکمل','بشپړ نوم'));manage_input('username',__t('Username','نام استفاده‌کننده','کارن نوم'));manage_input('password',__t('Temporary password','رمز موقت','لنډمهالی رمز'),'password');manage_input('confirm_password',__t('Confirm password','تکرار رمز','رمز تایید'),'password');?></div><fieldset><legend><?= __t('Assigned branches','شعبه‌های مجاز','مجازې څانګې') ?></legend><?php foreach($branches as $s):?><label><input type="checkbox" name="branch_ids[]" value="<?= (int)$s['id'] ?>"> <?= sanitize($s['name'].' · '.$s['city']) ?></label><?php endforeach ?></fieldset><details><summary><?= __t('Services and quotas','خدمات و سهمیه‌ها','خدمتونه او ونډې') ?></summary><?php manage_policies($central?'user':'owner_user',0) ?></details><button class="btn btn-primary"><?= __t('Create employee','ساخت حساب کارمند','کارمند جوړول') ?></button></form></details>
<?php $q=$pdo->prepare('SELECT u.id,u.fullname,u.username,u.status,u.role FROM users u JOIN shops s ON s.id=u.shop_id WHERE s.business_id=?');$q->execute([$b['id']]);foreach($q->fetchAll() as $u):if(!$central&&$u['role']!=='staff')continue;?>
