<?php if($u['role']==='staff'):$m=$pdo->prepare('SELECT shop_id FROM branch_memberships WHERE user_id=?');$m->execute([$u['id']]);$member=$m->fetchAll(PDO::FETCH_COLUMN);?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="edit_staff"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><input type="hidden" name="business_id" value="<?= (int)$b['id'] ?>"><?php manage_input('fullname',__t('Full name','نام مکمل','بشپړ نوم'),'text',$u['fullname']);?><select name="status" class="form-control"><?php foreach(['active','inactive'] as $status):?><option value="<?= $status ?>" <?= $status===$u['status']?'selected':'' ?>><?= $status==='active'?__t('Active','فعال','فعال'):__t('Inactive','غیرفعال','بند') ?></option><?php endforeach ?></select><?php foreach($branches as $s):?><label><input type="checkbox" name="branch_ids[]" value="<?= (int)$s['id'] ?>" <?= in_array($s['id'],$member)?'checked':'' ?>> <?= sanitize($s['name']) ?></label><?php endforeach ?><button class="btn btn-primary"><?= __t('Save account','ذخیرهٔ حساب','حساب خوندي کړئ') ?></button></form><?php endif ?>
<form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_policies"><input type="hidden" name="scope_type" value="user"><input type="hidden" name="scope_id" value="<?= (int)$u['id'] ?>"><?php manage_policies($central?'user':'owner_user',(int)$u['id']);?><button class="btn btn-primary"><?= __t('Save permissions','ذخیرهٔ صلاحیت‌ها','اجازې خوندي کړئ') ?></button></form></details>
